private val rw = new java.util.concurrent.locks.ReentrantReadWriteLock
private var cache = Map.empty[String, String]

def get(k: String): Option[String] = {
  val r = rw.readLock; r.lock()
  try cache.get(k) finally r.unlock()
}

def put(k: String, v: String): Unit = {
  val w = rw.writeLock; w.lock()
  try cache += (k -> v) finally w.unlock()
}
